is_intersects.example:
#include <cinux/region/memory_region.hpp>

using namespace cinux::base::memory;

void Example() {
    constexpr MemoryRegion first_page{0x1000, 0x2000};
    constexpr MemoryRegion shared_tail{0x1F00, 0x3000};
    static_assert(first_page.is_intersects(shared_tail));
    // true · 两个区间在 0x1F00..0x2000 这一段重叠

    constexpr MemoryRegion next_page{0x2000, 0x3000};
    static_assert(!first_page.is_intersects(next_page));
    // false · 端点 0x2000 相碰不算重叠
}
